/// <summary>
/// class <c>METTelemetryPOConfirmationErrorEvent</c> is used to log error event whenever purchase order confirmation error event.
/// </summary>
internal final class METTelemetryPOConfirmationErrorEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryPOConfirmationErrorEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryPOConfirmationErrorEvent</c> </returns>
public static METTelemetryPOConfirmationErrorEvent construct()
{
    return new METTelemetryPOConfirmationErrorEvent();
}

/// <summary>
/// Run confirmation journal error event 
/// </summary>
/// <param name = "_purchId"> purchase id </param>
/// <param name = "_error"> error message </param>
public static void runTelemetryEvent(PurchId _purchId, str _error)
{
    METTelemetryPOConfirmationErrorEvent pOConfirmationEvent = METTelemetryPOConfirmationErrorEvent::construct();

    pOConfirmationEvent.addRunTimePropertyToAppinsights(_purchId, _error);

    pOConfirmationEvent.processEvent(METTelemetryEventNames::POConfirmedErrorEvent);
}

/// <summary>
/// Initializes the parameter setup values.
/// </summary>
/// <param name = "_parameterSetup">The parameter setup record to initialize.</param>
protected void initializeParameterSetup(ISMTelemetryParameterSetup _parameterSetup)
{
    _parameterSetup.TelemetryClass = this.telemetryName();
    _parameterSetup.IsEnabled = NoYes::Yes;
    _parameterSetup.SeverityLevel = ISMTelemetrySeverityLevel::Error;
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_purchId"> purchId </c> </param>
public void addRunTimePropertyToAppinsights(PurchId _purchId, str _error)
{
    PurchTable purchTable = PurchTable::find(_purchId);

    this.addRuntimeProperty('PurchaseOrderId', purchTable.PurchId);
    this.addRuntimeProperty('warehouseId' ,purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', purchTable.VendorRef);
    this.addRuntimeProperty('VendorAccount', purchTable.OrderAccount);
    this.addRuntimeProperty('VendorAccount', purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', purchTable.VendorRef);
    this.addRuntimeProperty('BuyerGroup', purchTable.ItemBuyerGroupId);
    this.addRuntimeProperty('Message', _error);
}
